let peopleOffset=0,peopleQuery=0,editingMember=null;const peopleById=new Map();
function memberAvatar(u){const wrap=node('div',undefined,'member-avatar');if(u.picture){const img=node('img');img.src=u.picture;img.alt='';img.onerror=()=>{wrap.replaceChildren(node('span',u.name.slice(0,2).toUpperCase()))};wrap.append(img)}else wrap.textContent=u.name.slice(0,2).toUpperCase();return wrap}
async function loadPeople(more=false){const request=++peopleQuery,q=$('peopleSearch').value.trim(),offset=more?peopleOffset:0;const {users,total,counts}=await api('users?q='+encodeURIComponent(q)+'&offset='+offset+'&kind='+encodeURIComponent(peopleKind));if(request===peopleQuery&&counts)for(const o of $('peopleKind').options)o.textContent={all:'All',members:'Members',staff:'Admins & trusted sellers'}[o.value]+' ('+counts[o.value]+')';if(request!==peopleQuery)return;const root=$('controlPeople');if(!more){root.replaceChildren();peopleById.clear()}for(const u of users){peopleById.set(u.id,u);const row=node('div',undefined,'member-row'),copy=node('div',undefined,'member-row-copy');copy.append(node('strong',u.name));if(u.username)copy.append(node('small','@'+u.username));copy.append(node('small',u.email,'member-email'));copy.append(node('small',u.suspension?suspensionText(u.suspension):['can_post','can_message','can_start_deal'].filter(k=>!u.permissions?.[k]).map(k=>({can_post:'Posting off',can_message:'Messaging off',can_start_deal:'New deals off'}[k])).join(' · '),'member-capabilities'));const badges=node('div',undefined,'member-row-badges');if(u.verified)badges.append(node('span','✓ Blue verified','member-blue'));if(u.trusted_seller)badges.append(node('span','Trusted seller','member-seller'));if(u.role==='owner'||u.role==='trusted')badges.append(node('span',u.role==='owner'?'Owner':'Trusted admin','member-access'));if(u.role==='trusted')badges.append(node('span',u.deal_limit?'Deal limit ৳'+Number(u.deal_limit).toLocaleString('en-US'):'No deal limit','member-access'));copy.append(badges);const edit=button('✎',()=>openMemberEditor(u));edit.className='member-edit';edit.setAttribute('aria-label','Edit '+u.name);
 const tick=u.role==='owner'?null:button(u.verified?'✓ Verified':'Verify',async()=>{const give=!u.verified;if(!confirm(give?'Give '+u.name+' the blue tick (Verified member)? No application needed.':'Remove the blue tick from '+u.name+'?'))return;try{await api('verify',{userId:u.id,verified:give});u.verified=give;toast(give?'✅ '+u.name+' is now a Verified member.':'Blue tick removed from '+u.name+'.');await loadPeople()}catch(e){toast(e.message)}});if(tick){tick.className='member-verify'+(u.verified?' on':'');tick.title=u.verified?'Tap to remove the blue tick':'Give the blue tick without an application'}
 row.append(memberAvatar(u),copy,...(tick?[tick]:[]),edit);root.append(row)}peopleOffset=offset+users.length;$('memberSearchStatus').textContent=total+' member'+(total===1?'':'s')+(q?' found':'')+' · showing '+peopleOffset;$('loadMoreMembers').hidden=peopleOffset>=total;if(!peopleOffset)root.append(node('p','No matching members.','muted'))}
function openMemberEditor(u){editingMember=u;const copy=node('div');copy.append(node('strong',u.name),node('small',u.email),node('small',u.username?'@'+u.username:u.role));$('memberEditorIdentity').replaceChildren(memberAvatar(u),copy);$('memberBlueBadge').checked=!!u.verified;$('memberBlueBadge').disabled=u.role==='owner';$('memberSellerBadge').checked=!!u.trusted_seller;$('memberAccessRole').replaceChildren(new Option('Regular member','member'),...(loadedRules?.ownerOnly&&u.role!=='trusted'?[]:[new Option('Trusted admin','trusted')]));if(u.role==='owner')$('memberAccessRole').append(new Option('Website owner','owner'));$('memberAccessRole').value=u.role;$('memberAccessRole').disabled=u.role==='owner';$('memberDealLimit').value=u.deal_limit?String(u.deal_limit):'';$('memberDealLimitBox').hidden=u.role!=='trusted';$('memberAccessRole').onchange=()=>{$('memberDealLimitBox').hidden=$('memberAccessRole').value!=='trusted'};$('memberOwnerNote').hidden=u.role!=='owner';for(const [id,key] of [['memberCanPost','can_post'],['memberCanMessage','can_message'],['memberCanDeal','can_start_deal']]){$(id).checked=u.permissions?.[key]!==0;$(id).disabled=u.role==='owner'}$('memberRestoreAccount').hidden=!u.suspension;$('memberRestoreAccount').textContent=u.suspension&&isBan(u.suspension)?'Remove ban':'Restore suspended account';$('memberSuspendBox').hidden=u.role==='owner';$('memberSuspendStatus').textContent=u.suspension?suspensionText(u.suspension)+(u.suspension.reason?' — '+u.suspension.reason:'')+(u.suspension.appealed===1?' · ✉️ Appeal waiting: "'+(u.suspension.appeal_text||'')+'" (answer it in Overview)':u.suspension.appealed===2?' · Ban kept after appeal':''):'Active account. Not suspended.';$('memberSuspendReason').value='';$('memberSuspendLength').value='24';$('memberSuspendCustom').hidden=true;paintSuspendButton();$('memberPermissionSummary').textContent=u.role==='owner'?'Owner: full website and control room access.':u.role==='trusted'?'Trusted admin: manages own groups and assigned deals. No member emails or owner controls.':'Member: own posts, private conversations and participating deals.';$('memberEditorModal').hidden=false}
$('closeMemberEditor').onclick=()=>$('memberEditorModal').hidden=true;$('memberEditorModal').onclick=e=>{if(e.target===$('memberEditorModal'))$('memberEditorModal').hidden=true};$('loadMoreMembers').onclick=()=>void loadPeople(true).catch(e=>toast(e.message));
$('memberEditorForm').onsubmit=async e=>{e.preventDefault();if(!editingMember)return;if(editingMember.verified&&!$('memberBlueBadge').checked&&!confirm('Remove the blue tick (Verified member badge) from '+editingMember.name+'?'))return;if(!editingMember.verified&&$('memberBlueBadge').checked&&!confirm('Give '+editingMember.name+' the blue tick (Verified member badge)?'))return;e.submitter.disabled=true;try{await api('member-access',{userId:editingMember.id,verified:$('memberBlueBadge').checked,trustedSeller:$('memberSellerBadge').checked,role:$('memberAccessRole').value,permissions:{can_post:$('memberCanPost').checked,can_message:$('memberCanMessage').checked,can_start_deal:$('memberCanDeal').checked}});if($('memberAccessRole').value==='trusted'){const v=$('memberDealLimit').value.trim();await api('deal-limit',{userId:editingMember.id,maxAmount:v||null})}$('memberEditorModal').hidden=true;await loadPeople();toast('Member badges and access saved.')}catch(err){toast(err.message)}finally{e.submitter.disabled=false}};
async function loadReports(){
 const all=(await api('reports')).reports,root=$('controlReports');root.replaceChildren();
 const reports=all.filter(r=>reportKind==='post'?!!r.post_id:reportKind==='scam'?!r.post_id&&r.reason==='scam':!r.post_id&&r.reason!=='scam');
 $('reportsHeading').textContent={post:'📝 Post reports',scam:'⚠️ Scammer reports',help:'💬 Help & website issues'}[reportKind];$('reportsIntro').textContent={post:'Posts members reported. Resolve, dismiss or restrict the post.',scam:'Members who reported a scammer, with their details and screenshot.',help:'Help questions, website issues and other messages from members.'}[reportKind];
 for(const b of document.querySelectorAll('[data-report-tab]'))b.setAttribute('aria-selected',String(b.dataset.reportTab===reportKind));
 if(!reports.length)root.append(node('p','Nothing here yet.','muted'));
 for(const r of reports){
  const card=node('article',undefined,'card report-card');
  const head=node('div',undefined,'report-head');head.append(node('span',r.status,'pill pill-'+r.status),node('strong',r.reason.replaceAll('-',' '),'report-reason'));
  const title=node('h3',undefined,'report-title');if(r.post_id){const a=node('a',r.post_title||'Reported post');a.href='/post/'+r.post_id;a.target='_blank';a.rel='noopener';a.title='Open the post';title.append(a,node('span',' ↗','muted'))}else title.textContent='Website issue';
  const by=node('p',undefined,'small muted');const who=node('a',r.reporter_name);who.href=profileUrl(r.user_id);who.target='_blank';who.rel='noopener';by.append('By ',who,' · '+shortId(r.user_id)+' · '+new Date(r.created_at).toLocaleString());
  card.append(head,title,by,node('p',r.details,'report-details'));if(r.resolution_note)card.append(node('p','📝 Your answer: '+r.resolution_note,'small report-answer'));
  if(r.post_details)card.append(node('blockquote',r.post_details,'reported-post-details'));
  if(r.attachment_id){const label=node('p','Attached screenshot (private)','small muted'),img=node('img');img.src='/api/control/evidence/'+encodeURIComponent(r.attachment_id);img.alt='Screenshot attached to report';img.loading='lazy';img.style.maxWidth='min(100%,380px)';img.style.maxHeight='360px';img.style.objectFit='contain';img.style.borderRadius='12px';card.append(label,img)}
  if(r.status==='open'){const actions=node('div',undefined,'action-row');for(const [action,label]of [['resolve','Mark resolved'],['dismiss','Dismiss'],...(r.post_id?[['restrict','Restrict reported post']]:[])])actions.append(button(label,async()=>{const note=prompt((action==='dismiss'?'Why was it not accepted?':'What did you do?')+' (the member sees this; leave empty for the standard message)','');if(note===null)return;await api('report-action',{reportId:r.id,action,note});toast('Answer sent to '+r.reporter_name+'.');await loadReports()}));card.append(actions)}
  root.append(card);
 }
}
async function refreshVerificationCount(){try{const {requests}=await api('verifications'),count=k=>requests.filter(r=>r.status==='pending'&&r.kind===k).length;$('verificationsNav').textContent='🛡️ Admin applications'+(count('trusted')?' ('+count('trusted')+')':'');$('verificationsMemberNav').textContent='✔️ Verified member applications'+(count('seller')?' ('+count('seller')+')':'');return requests}catch{return []}}
async function loadVerificationPage(){const root=$('verificationList');root.replaceChildren();$('verificationHeading').textContent=verifyKind==='trusted'?'🛡️ Admin applications':'✔️ Verified member applications';for(const b of document.querySelectorAll('[data-verify-tab]'))b.setAttribute('aria-selected',String(b.dataset.verifyTab===verifyKind));await loadVerificationApplications(root);void refreshVerificationCount(true)}
async function loadVerificationApplications(root){
 const section=node('section',undefined,'verification-review-section');
 try{
  const requests=(await api('verifications')).requests.filter(r=>r.kind===verifyKind);
  if(!requests.length)section.append(node('p','No verification applications yet.','muted'));
  for(const r of requests){
   const card=node('article',undefined,'card report-card');card.append(node('h3',r.applicant_name+' · '+(r.kind==='seller'?'Seller verification':'Trusted Admin application')),idLine(r.user_id,' · Sent '+new Date(r.created_at).toLocaleString()),node('p',r.status==='pending'?'⏳ Waiting for you':r.status==='approved'?'✅ Approved':'❌ Rejected','pill'),...(r.contact?[node('p','Contact (owner only): '+r.contact,'small')]:[]));
   if(r.whatsapp){const wa=node('a','🟢 WhatsApp 0'+r.whatsapp.slice(3),'btn');wa.href='https://wa.me/'+r.whatsapp;wa.target='_blank';wa.rel='noopener';card.append(wa)}
   if(Number.isFinite(r.location_lat)){const map=node('a','📍 See location on map (about '+Math.round(r.location_accuracy||0)+' m)','btn');map.href='https://maps.google.com/?q='+r.location_lat+','+r.location_lng;map.target='_blank';map.rel='noopener';card.append(map,node('p','Location shared '+new Date(r.location_at).toLocaleString(),'small muted'))}
   const answers=(()=>{try{return JSON.parse(r.answers||'[]')}catch{return []}})();if(answers.length){const list=node('dl',undefined,'verification-answers');for(const x of answers)list.append(node('dt',x.q),node('dd',x.a||'—'));card.append(list)}
   {const docName={nid:'🪪 NID card',passport:'🛂 Passport',driving:'🚗 Driving licence',birth:'📄 Birth certificate',student:'🎓 Student ID'}[r.doc_type||'nid']||'Document';card.append(node('p','Document: '+docName,'small'));const shots=node('div',undefined,'verification-shots');for(const [id,label] of [[r.document_id,'Front'],[r.back_document_id,'Back']]){if(!id)continue;const fig=node('figure');const img=node('img');img.src='/api/control/evidence/'+encodeURIComponent(id);img.alt=label+' of the identity document';img.loading='lazy';fig.append(img,node('figcaption',label));shots.append(fig)}card.append(shots)}
   if(r.status==='pending'){const actions=node('div',undefined,'action-row');for(const [action,label]of [['approve','✅ Approve · give blue tick'],['reject','❌ Reject']])actions.append(button(label,async()=>{const note=prompt(action==='approve'?'Approve '+r.applicant_name+' and give the blue tick? Optional message for them:':'Reject this application? Tell them why (they see this):','');if(note===null)return;const result=await api('verification-action',{id:r.id,action,note});toast(action==='approve'?(result.verified?'✅ '+r.applicant_name+' now has the blue tick.':'Approved.'):'Application rejected.');await loadVerificationPage()}));card.append(actions)}
   section.append(card);
  }
 }catch(err){section.append(node('p','Could not load verification applications: '+err.message,'muted'))}
 root.append(section);
}

