let controlDealStatus='current',controlDealQuery=0,controlDealSearchTimer;
async function loadControlDeals(){
 const request=++controlDealQuery,params=new URLSearchParams({status:controlDealStatus,q:$('controlDealSearch').value});
 const {deals,summary}=await api('deals?'+params);if(request!==controlDealQuery)return;
 const tabs=$('controlDealTabs');tabs.replaceChildren();
 for(const [value,label]of [['current','Ongoing'],['pending','Pending'],['active','Active'],['disputed','Disputed'],['completed','Previous deals'],['cancelled','Cancelled']]){const tab=button(label,async()=>{controlDealStatus=value;await loadControlDeals()});tab.className='deal-filter-tab';tab.setAttribute('role','tab');tab.setAttribute('aria-selected',String(value===controlDealStatus));tabs.append(tab)}
 const root=$('controlDeals');root.replaceChildren();const summaryCard=node('div',undefined,'card');summaryCard.append(node('strong',(summary?.total||0)+' completed deals'));for(const a of summary?.admins||[])summaryCard.append(node('p',a.name+' · '+a.completed+' completed','hint'));root.append(summaryCard);if(!deals.length)root.append(node('p','No matching deals.','muted'));
 for(const d of deals){
  const c=node('article',undefined,'card control-deal-card');c.append(node('span',d.status.replaceAll('_',' '),'pill'),node('h2',d.account_title||d.title||'Marketplace account'),node('p',d.deal_code+' · '+d.listing_code),node('p','Buyer: '+d.buyer_name+' · Seller: '+d.seller_name),node('p','৳'+d.price.toLocaleString('en-BD')+' · Admin: '+d.admin_name));
  if(d.cancel_pending)c.append(node('p','Cancellation requested · awaiting your decision\n'+(d.cancel_reasons||''),'control-cancel-notice'));
  const assigned=d.admin_id===controlUser?.id,pending=['proposed','awaiting_admin','awaiting_seller','open','admin_proposed'].includes(d.status),open=pending||['active','awaiting_final','disputed'].includes(d.status);
  if(assigned){
   const actions=[];
   if(['awaiting_admin','proposed'].includes(d.status)&&d.buyer_ok&&(d.mode==='direct'||d.seller_ok))actions.push(['accept','Accept deal']);
   if(pending)actions.push(['reject','Reject request']);if(open&&!(d.flow===1&&d.admin_id===d.seller_id&&controlUser?.role!=='owner'&&(d.paid_at||d.funded_at||d.status==='disputed')))actions.push(['cancel','Cancel deal']);if(open&&d.cancel_pending)actions.push(['reject_cancel','Decline cancellation']);
   if(d.flow===1){if(d.status==='active'&&!d.funded_at&&d.admin_id===controlUser?.id)actions.push(['confirm_payment','✅ Money received']);if(['active','awaiting_final'].includes(d.status)&&d.delivered_at&&!d.cancel_pending&&d.admin_id===controlUser?.id)actions.push(['finalize','💸 Seller paid · complete deal']);if(d.status==='disputed'){actions.push(['resolve_dispute','▶️ Resume deal']);actions.push(['resolve_redeliver','🔁 Seller gives the ID again'])}}
   else{if(d.mode==='direct'&&d.seller_id===controlUser?.id&&d.status==='active'&&!d.seller_done)actions.push(['complete','Confirm seller completion']);if(['active','awaiting_final'].includes(d.status)&&!d.cancel_pending&&d.seller_done&&(d.buyer_done||d.mode==='direct'))actions.push(['finalize',d.buyer_done?'Admin final confirmation':'Second Admin confirmation']);if(d.status==='disputed')actions.push(['resolve_dispute','▶️ Continue deal'])}
   if(d.flow===1)c.append(node('p',d.status==='disputed'?'⚠️ Dispute: '+(d.dispute_reason||'see deal room'):d.buyer_done?'🎉 Buyer got the ID · send the money to the seller':d.delivered_at?'🔑 ID handed over · buyer checking':d.funded_at?'🔒 Money with Admin · waiting for the seller':d.paid_at?'🧾 Buyer sent the money (screenshot in Deal Room)':'⏳ Waiting for the buyer to pay','muted'));
   for(const [action,label]of actions)c.append(button(label,async()=>{if(['cancel','reject'].includes(action)&&!confirm(label+'?'))return;let extra={};if(d.flow===1){if(action==='confirm_payment'&&!confirm('💰 Is the money really in your account?'))return;if(action==='finalize'){if(!confirm('💸 Did you send the money to the seller? Complete this deal now?'))return;extra={payout:(prompt('Note (optional):')||'').trim()}}if(action==='resolve_redeliver'){await api('deals/'+d.id+'/action',{action:'resolve_dispute',redeliver:true,version:d.version});await loadControlDeals();return}await api('deals/'+d.id+'/action',{action,version:d.version,...extra});await loadControlDeals();return}if(action==='finalize'&&!d.buyer_done){const reason=prompt('Buyer has not confirmed. Give a reason for completing this direct deal as Admin:');if(!reason?.trim()||!confirm('This is your second Admin confirmation. Finally complete this deal without buyer confirmation?'))return;extra={doubleConfirm:true,reason:reason.trim()}}await api('deals/'+d.id+'/action',{action,version:d.version,...extra});await loadControlDeals()}));
  }
  c.append(button('Status history',async()=>{const {events}=await api('deals/'+d.id+'/history');let history=c.querySelector('.control-deal-history');if(!history){history=node('div',undefined,'control-deal-history');c.append(history)}history.replaceChildren();for(const event of events)history.append(node('p',event.name+' · '+event.action.replaceAll('_',' ')+' · '+new Date(event.created_at).toLocaleString(),'hint'))}));
  const link=node('a','Open in Deals →','btn secondary');link.href='/?deal='+encodeURIComponent(d.id)+'#deals';c.append(link);root.append(c);
 }
}
