let pwaLogoObjectUrl=null;
async function loadPwaSettings(){const config=await api('pwa');$('pwaName').value=config.name;$('pwaShortName').value=config.shortName;$('pwaDescription').value=config.description;$('pwaNamePreview').textContent=config.name;$('pwaLogoPreview').src=config.icons[0].src;$('pwaResetLogo').checked=false;$('pwaLogo').value='';$('pwaSaveStatus').textContent=''}
$('pwaName').oninput=()=>$('pwaNamePreview').textContent=$('pwaName').value||'App name';
$('pwaLogo').onchange=()=>{const file=$('pwaLogo').files[0];if(pwaLogoObjectUrl)URL.revokeObjectURL(pwaLogoObjectUrl);if(!file)return;if(file.size>8*1024*1024){$('pwaLogo').value='';return toast('Choose a logo up to 8 MB.')}pwaLogoObjectUrl=URL.createObjectURL(file);$('pwaLogoPreview').src=pwaLogoObjectUrl;$('pwaResetLogo').checked=false};
$('pwaResetLogo').onchange=()=>{if($('pwaResetLogo').checked){$('pwaLogo').value='';$('pwaLogoPreview').src='/icons/app-192.png'}};
async function appIconBlob(image,size,maskable=false){const canvas=document.createElement('canvas');canvas.width=canvas.height=size;const ctx=canvas.getContext('2d');ctx.fillStyle='#0b1428';ctx.fillRect(0,0,size,size);const bound=maskable?size*.62:size,scale=Math.min(bound/image.width,bound/image.height),width=image.width*scale,height=image.height*scale;ctx.drawImage(image,(size-width)/2,(size-height)/2,width,height);return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Could not prepare app logo')),'image/png'))}
$('controlPwaForm').onsubmit=async e=>{
 e.preventDefault();const button=e.submitter;button.disabled=true;
 try{let icons;const file=$('pwaLogo').files[0];if(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('Choose a PNG, JPG or WebP up to 8 MB.');const image=await createImageBitmap(file);icons={};try{for(const [key,size,maskable]of [['icon192Id',192,false],['icon512Id',512,false],['iconMaskableId',512,true]]){$('pwaSaveStatus').textContent='Preparing and uploading app logo…';const blob=await appIconBlob(image,size,maskable),response=await fetch('/api/control/upload',{method:'POST',credentials:'same-origin',headers:{'content-type':'image/png'},body:blob}),data=await response.json();if(!response.ok)throw Error(data.error);icons[key]=data.id}}finally{image.close()}}
 await api('pwa',{name:$('pwaName').value,shortName:$('pwaShortName').value,description:$('pwaDescription').value,resetIcons:$('pwaResetLogo').checked,...(icons?{icons}:{})});await loadPwaSettings();toast('Website and app name, description and logo saved.');
 }catch(error){$('pwaSaveStatus').textContent=error.message;toast(error.message)}finally{button.disabled=false}
};

