function updateMetaCounts(){$('metaTitleCount').textContent=$('siteMetaTitle').value.length+' / 60';$('metaDescriptionCount').textContent=$('siteMetaDescription').value.length+' / 160'}
async function loadWebsiteSettings(){const [site,config,appearance]=await Promise.all([fetch('/api/site').then(r=>r.json()),api('pwa'),fetch('/api/appearance').then(r=>r.json())]);savedAppearance=appearance;layoutOrder=[...appearance.navOrder];layoutLabels={...appearance.navLabels};$('controlSiteName').value=config.name;$('controlWelcome').value=site.welcome;$('siteSlogan').value=appearance.slogan;$('siteMetaTitle').value=appearance.metaTitle||config.name;$('siteMetaDescription').value=appearance.metaDescription||config.description;$('siteLogoPreview').src=config.icons[0].src;$('siteBrandPreview').textContent=config.name;$('siteLogoInput').value='';$('siteSaveStatus').textContent='';$('layoutFeedTitle').value=appearance.feedTitle;$('layoutDensity').value=appearance.density;updateMetaCounts();renderNavigationEditor();void loadMarketRulesForm().catch(error=>toast(error.message));void loadFeedPresets().catch(error=>toast(error.message))}
