$('siteMetaTitle').oninput=$('siteMetaDescription').oninput=updateMetaCounts;$('reloadSiteSettings').onclick=()=>void loadWebsiteSettings().catch(e=>toast(e.message));$('controlSiteName').oninput=()=>$('siteBrandPreview').textContent=$('controlSiteName').value;
