let loadedRules={};
async function loadMarketRulesForm(){const {rules}=await fetch('/api/market-rules',{cache:'no-store'}).then(r=>r.json());loadedRules=rules;const root=$('rulesFields');root.replaceChildren();for(const [key,type,label,hint]of RULE_FIELDS){if(key==='section'){root.append(node('h3',type,'rules-section'));continue}if(type==='switch'){const row=node('label',undefined,'rule-switch');const input=node('input');input.type='checkbox';input.id='rule-'+key;input.checked=!!rules[key];row.append(input,node('span',label));root.append(row)}else{const l=node('label',label);l.htmlFor='rule-'+key;const input=node('input',undefined,'input');input.type='number';input.id='rule-'+key;input.min='0';input.step='1';input.required=true;input.value=String(rules[key]);root.append(l,input)}if(hint)root.append(node('p',hint,'hint'))}}
$('controlRulesForm').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const data={...loadedRules};for(const [key,type]of RULE_FIELDS){if(key==='section')continue;const input=$('rule-'+key);data[key]=type==='switch'?input.checked:Number(input.value)}await api('market-rules',data);toast('✅ Marketplace rules saved.')}catch(error){toast(error.message)}finally{submit.disabled=false}};
// Password help: requests from members, member search, and one-time reset links sent from the Owner's own WhatsApp / email.
const prettyLogin=login=>/^8801\d{9}$/.test(login)?'0'+login.slice(3):login;
async function refreshResetCount(){try{const {requests}=await api('reset-requests');$('resetsNav').textContent='🔑 Forgot password'+(requests.length?' ('+requests.length+')':'');return requests}catch{return []}}
function resetShare(box,data){
 box.replaceChildren();const link=node('input',undefined,'input');link.value=data.link;link.readOnly=true;link.onclick=()=>link.select();
 const where=data.kind==='phone'?'WhatsApp '+prettyLogin(data.login):data.login,text='Hello '+data.name+', here is your '+(document.title.split(' — ')[0]||'WizeNex')+' password reset link. It works once, for 24 hours: '+data.link;
 box.append(node('p','✅ Link ready for '+data.name+'. Send it only to '+where+'.','muted'),link);const row=node('div',undefined,'reset-share');
 if(data.kind==='phone'){const wa=node('a','🟢 Send on WhatsApp','btn');wa.href='https://wa.me/'+data.login+'?text='+encodeURIComponent(text);wa.target='_blank';wa.rel='noopener';row.append(wa)}
 else{const mail=node('a','✉️ Send by email','btn');mail.href='mailto:'+data.login+'?subject='+encodeURIComponent('Your password reset link')+'&body='+encodeURIComponent(text);row.append(mail)}
 row.append(button('📋 Copy link',async()=>{await navigator.clipboard.writeText(data.link);toast('Link copied.')}));box.append(row);
}
function resetRow(person,{requestId,when}={}){
 const card=node('div',undefined,'reset-row'),head=node('div',undefined,'reset-row-head'),box=node('div',undefined,'reset-share-box');
 head.append(node('strong',person.name||'❓ No account found'),node('span',(person.kind==='phone'?'📱 ':'✉️ ')+prettyLogin(person.login),'muted'));if(when)head.append(node('small','Asked '+new Date(when).toLocaleString(),'muted'));card.append(head);
 const actions=node('div',undefined,'reset-actions');
 if(person.user_id&&person.has_password!==0)actions.append(button('🔗 Make reset link',async()=>{const data=await api('reset-link',{userId:person.user_id});resetShare(box,data);void refreshResetCount(true)}));
 else if(person.user_id)actions.append(node('span','This member uses Google sign-in.','muted'));
 else actions.append(node('span','Nobody has an account with this '+(person.kind==='phone'?'number':'email')+'. Ask them which one they used.','muted'));
 if(requestId)actions.append(button('✖️ Dismiss',async()=>{await api('reset-requests/dismiss',{id:requestId});await loadResetRequests()}));
 card.append(actions,box);return card;
}
async function loadResetRequests(){
 const root=$('resetRequests'),requests=await refreshResetCount(true);root.replaceChildren();
 if(!requests.length)root.append(node('p','No requests right now.','muted'));
 for(const r of requests)root.append(resetRow(r,{requestId:r.id,when:r.created_at}));
}
let resetSearchTimer;
$('resetSearch').oninput=()=>{clearTimeout(resetSearchTimer);resetSearchTimer=setTimeout(async()=>{const q=$('resetSearch').value.trim(),root=$('resetSearchResults');root.replaceChildren();if(q.length<2)return;try{const {accounts}=await api('password-accounts?q='+encodeURIComponent(q));if(!accounts.length)root.append(node('p','No WhatsApp / email account found. Google members do not use passwords.','muted'));for(const a of accounts)root.append(resetRow(a))}catch(error){root.append(node('p',error.message,'muted'))}},300)};

