const restrictLabel=h=>h<24?h+' hour'+(h===1?'':'s'):(h/24)+' day'+(h===24?'':'s');
const chatText=t=>{t=String(t||'');return t.startsWith('media:image/')?'📷 Photo':t.startsWith('media:video/')?'🎥 Video':t.startsWith('media:audio/')?'🎤 Voice message':t};
