 if(restricted.length){const box=node('div',undefined,'card restricted-box');box.append(node('h3','🚫 Restricted now'));for(const r of restricted){const row=node('div',undefined,'restricted-row');row.append(node('strong',r.name),node('small','until '+new Date(r.until_at).toLocaleString(),'muted'),button('🔓 Remove',async()=>{if(!confirm('Remove the chat restriction for '+r.name+'?'))return;await api('chat-restriction',{userId:r.user_id});toast('Restriction removed.');await loadChatReports()}));box.append(row)}top.append(box)}
