  head.append(node('span',r.status==='open'?'⏳ Waiting for you':r.status==='actioned'?'✅ '+r.action:'➖ '+(r.action||'Dismissed'),'pill'),node('span',REPORT_REASONS[r.reason]||r.reason,'chat-report-reason'));card.append(head);
  card.append(node('h3',r.target_name),node('p',r.target_reports+' report'+(r.target_reports===1?'':'s')+' about this member'+(r.restricted_until?' · 🚫 restricted until '+new Date(r.restricted_until).toLocaleString():''),'small'),node('p','Reported by '+r.reporter_name+' · '+(r.kind==='group'?'Group: '+(r.group_name||'group'):'Personal chat')+' · '+new Date(r.created_at).toLocaleString(),'small muted'));
  const msg=node('div',undefined,'chat-report-message');if(r.context.length)msg.append(node('small','Earlier messages from this member','muted'));for(const c of r.context)msg.append(node('p',chatText(c.text),'context'));msg.append(node('small','Reported message','muted'),node('p',chatText(r.message_text),'reported'));card.append(msg);
  if(r.details)card.append(node('p','“'+r.details+'”','chat-report-details'));
