// Owner: suspend for a while or ban for good. A ban ends only when the owner restores the account.
const BAN_FOREVER=253402300799000;
function isBan(s){return Number(s?.until_at)>=BAN_FOREVER}
function suspensionText(s){return isBan(s)?'⛔ Banned (no end date)':'⏳ Suspended until '+new Date(s.until_at).toLocaleString()}
function suspendHours(){const v=$('memberSuspendLength').value;if(v==='forever')return null;if(v==='custom')return Number($('memberSuspendAmount').value)*Number($('memberSuspendUnit').value);return Number(v)}
function paintSuspendButton(){const v=$('memberSuspendLength').value;$('memberSuspendCustom').hidden=v!=='custom';$('memberSuspendButton').textContent=v==='forever'?'Ban member':'Suspend member'}
$('memberSuspendLength').onchange=paintSuspendButton;
$('memberSuspendButton').onclick=async()=>{if(!editingMember)return;const forever=$('memberSuspendLength').value==='forever',hours=suspendHours();if(!forever&&!(hours>=1&&hours<=8760)){toast('Choose 1 hour to 365 days.');return}
 const length=forever?'permanently':hours%24===0?'for '+(hours/24)+' day'+(hours===24?'':'s'):'for '+hours+' hour'+(hours===1?'':'s');if(!confirm((forever?'Ban ':'Suspend ')+editingMember.name+' '+length+'?'))return;
 const b=$('memberSuspendButton');b.disabled=true;try{await api('suspend',{userId:editingMember.id,forever,hours:forever?undefined:hours,reason:$('memberSuspendReason').value.trim()||undefined});$('memberEditorModal').hidden=true;await loadPeople();toast(forever?'Member banned.':'Member suspended '+length+'.')}catch(e){toast(e.message)}finally{b.disabled=false}};

// My feed price buttons (owner): rows of minimum / maximum, move up/down, remove.
let feedPresetList=[];
const takaIn=v=>{v=String(v??'').trim().toLowerCase().replace(/[,৳\s]/g,'');if(!v)return null;const k=v.endsWith('k');const n=Number(k?v.slice(0,-1):v)*(k?1000:1);return Number.isFinite(n)&&n>=0?Math.round(n):NaN};
const takaOut=n=>n==null?'':n>=1000&&n%1000===0?(n/1000)+'k':String(n);
const presetText=p=>{const s=n=>n>=1000?Number((n/1000).toFixed(3))+'k':String(n);return p.min==null?'Under '+s(p.max):p.max==null?s(p.min)+'+':s(p.min)+'–'+s(p.max)};
function readFeedPresets(){return [...$('feedPresetRows').querySelectorAll('.feed-preset-row')].map(r=>({min:takaIn(r.querySelector('[data-k=min]').value),max:takaIn(r.querySelector('[data-k=max]').value)}))}
function paintFeedPresetPreview(){const list=readFeedPresets(),ok=list.filter(p=>!Number.isNaN(p.min)&&!Number.isNaN(p.max)&&(p.min!=null||p.max!=null));$('feedPresetPreview').textContent='Feed-e dekhabe: Any · '+ok.map(presetText).join(' · ')}
function paintFeedPresets(){const root=$('feedPresetRows');root.replaceChildren();feedPresetList.forEach((p,i)=>{const row=node('div',undefined,'feed-preset-row');const min=node('input',undefined,'input');min.dataset.k='min';min.placeholder='Min (empty = 0)';min.value=takaOut(p.min);min.inputMode='decimal';const max=node('input',undefined,'input');max.dataset.k='max';max.placeholder='Max (empty = no limit)';max.value=takaOut(p.max);max.inputMode='decimal';for(const x of [min,max])x.oninput=paintFeedPresetPreview;
 const up=node('button','↑','btn ghost');up.type='button';up.disabled=i===0;up.onclick=()=>{feedPresetList=readFeedPresets();[feedPresetList[i-1],feedPresetList[i]]=[feedPresetList[i],feedPresetList[i-1]];paintFeedPresets()};
 const down=node('button','↓','btn ghost');down.type='button';down.disabled=i===feedPresetList.length-1;down.onclick=()=>{feedPresetList=readFeedPresets();[feedPresetList[i+1],feedPresetList[i]]=[feedPresetList[i],feedPresetList[i+1]];paintFeedPresets()};
 const del=node('button','✕','btn ghost danger');del.type='button';del.onclick=()=>{feedPresetList=readFeedPresets();feedPresetList.splice(i,1);paintFeedPresets()};
 row.append(min,node('span','–','feed-preset-dash'),max,up,down,del);root.append(row)});paintFeedPresetPreview()}
async function loadFeedPresets(){const d=await fetch('/api/feed-presets',{cache:'no-store'}).then(r=>r.json());feedPresetList=d.presets;paintFeedPresets()}
$('addFeedPreset').onclick=()=>{feedPresetList=readFeedPresets();if(feedPresetList.length>=12)return toast('12 ta porjonto button.');feedPresetList.push({min:null,max:null});paintFeedPresets();$('feedPresetRows').lastElementChild?.querySelector('input')?.focus()};
$('resetFeedPresets').onclick=async()=>{if(!confirm('Default price buttons e fire jaben?'))return;try{const d=await api('feed-presets',{reset:true});feedPresetList=d.presets;paintFeedPresets();toast('Default price buttons.')}catch(e){toast(e.message)}};
$('feedPresetsForm').onsubmit=async e=>{e.preventDefault();const list=readFeedPresets();if(list.some(p=>Number.isNaN(p.min)||Number.isNaN(p.max)))return toast('Price likhun 5000 ba 5k er moto.');const b=e.submitter;b.disabled=true;try{const d=await api('feed-presets',{presets:list});feedPresetList=d.presets;paintFeedPresets();toast('Price buttons saved. My feed e ekhon notun button dekhabe.')}catch(err){toast(err.message)}finally{b.disabled=false}};

// Short account ID (first 8 characters), like a Deal ID. The full ID is still used inside the panel.
function shortId(id){return '#'+String(id||'').slice(0,8).toUpperCase()}
function profileUrl(id){return location.origin+'/id/'+String(id||'').slice(0,8).toLowerCase()}

// Faster panel: the side counters (password resets, verifications, maintenance, chat reports) refresh at most every 30 seconds,
// not on every page switch. Saving or answering something still updates the page you are on right away.
for(const name of ['refreshResetCount','refreshVerificationCount','refreshMaintenance','refreshChatReportCount']){const base=globalThis[name];if(typeof base!=='function')continue;let last=0,running=null;globalThis[name]=function(force){const now=Date.now();if(!force&&now-last<30000)return running||Promise.resolve();last=now;running=Promise.resolve(base.apply(this,arguments)).finally(()=>{running=null});return running}}

function idLine(id,rest){const line=node('p',undefined,'small muted');const a=node('a',shortId(id));a.href=profileUrl(id);a.target='_blank';a.rel='noopener';a.title='Open this member’s profile';line.append('Account ID: ',a,rest);return line}

// Reports and Posts & safety are one area: tabs jump between them.
document.querySelector('[data-goto-posts]')?.addEventListener('click',()=>void view('posts'));
for(const b of document.querySelectorAll('[data-goto-report]'))b.addEventListener('click',()=>{reportKind=b.dataset.gotoReport;void view('reports')});

// Videos in the posts check: a small thumbnail with ▶ and its length (no player menu that runs off a phone screen).
// Tap opens a player that fits the screen.
function adminVideoThumb(m,title){const b=node('button',undefined,'admin-video-thumb');b.type='button';b.setAttribute('aria-label','Play video of '+title);const v=node('video');v.src=m.url+'#t=0.5';v.preload='metadata';v.muted=true;v.playsInline=true;const len=node('span','🎬','admin-video-len');v.onloadedmetadata=()=>{if(isFinite(v.duration)){const s=Math.round(v.duration);len.textContent='▶ '+Math.floor(s/60)+':'+String(s%60).padStart(2,'0')+(s>120?' · over 2 min':'');if(s>120)b.classList.add('too-long')}};b.append(v,len);b.onclick=()=>openAdminMedia(m,title);return b}
function openAdminMedia(m,title){const box=node('div',undefined,'admin-media-viewer');box.onclick=e=>{if(e.target===box)box.remove()};const close=node('button','×','admin-media-close');close.type='button';close.onclick=()=>box.remove();const el=node(m.type.startsWith('video/')?'video':'img');el.src=m.url;if(el.tagName==='VIDEO'){el.controls=true;el.autoplay=true;el.playsInline=true;el.setAttribute('controlsList','nodownload noplaybackrate')}else el.alt=title;box.append(el,close);document.body.append(box)}
